// HasBundle applies the HasEdge predicate on the "bundle" edge.
func HasBundle() predicate.BundlePrivacyDeclarations {
	return predicate.BundlePrivacyDeclarations(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, BundleTable, BundleColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBundleWith applies the HasEdge predicate on the "bundle" edge with a given conditions (other predicates).
func HasBundleWith(preds ...predicate.Bundles) predicate.BundlePrivacyDeclarations {
	return predicate.BundlePrivacyDeclarations(func(s *sql.Selector) {
		step := newBundleStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundlePrivacyDeclarations) predicate.BundlePrivacyDeclarations {
	return predicate.BundlePrivacyDeclarations(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundlePrivacyDeclarations) predicate.BundlePrivacyDeclarations {
	return predicate.BundlePrivacyDeclarations(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundlePrivacyDeclarations) predicate.BundlePrivacyDeclarations {
	return predicate.BundlePrivacyDeclarations(sql.NotPredicates(p))
}
